#!/bin/bash
set -euo pipefail

# Authorize the SOAR engine's responder key (generated by the soar-keygen init service).
for _ in $(seq 1 30); do
  [ -f /soar-keys/id_ed25519.pub ] && break
  sleep 1
done
if [ -f /soar-keys/id_ed25519.pub ]; then
  install -o soar -g soar -m 600 /soar-keys/id_ed25519.pub /home/soar/.ssh/authorized_keys
fi

# nginx logs to files (the image symlinks them to stdout by default in some variants).
rm -f /var/log/nginx/access.log /var/log/nginx/error.log
touch /var/log/auth.log /var/log/syslog /var/log/nginx/access.log /var/log/nginx/error.log
chown syslog:adm /var/log/auth.log /var/log/syslog || true

rsyslogd
nginx
/var/ossec/bin/wazuh-control start

echo "target-victim ready (sshd + nginx + wazuh-agent)"
exec /usr/sbin/sshd -D
